import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "../../api/client";

const blank = { name: "", slug: "", description: "" };
export default function Categories() {
  const [categories, setCategories] = useState([]);
  const [form, setForm] = useState(blank);
  const [editing, setEditing] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const reload = async () => setCategories(await api.categories.list());
  useEffect(() => { let active = true; api.categories.list().then((data) => { if (active) setCategories(data); }).catch((requestError) => { if (active) setError(requestError.message); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, []);
  const setName = (name) => setForm((current) => ({ ...current, name, slug: editing ? current.slug : name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") }));
  const submit = async (event) => { event.preventDefault(); setError(""); setNotice(""); setSaving(true); const payload = { name: form.name.trim(), slug: form.slug.trim().toLowerCase(), description: form.description.trim() }; try { if (editing) { const result = await api.categories.update(editing, payload); setNotice(result.message); } else { const result = await api.categories.create(payload); setNotice(result.message); } setForm(blank); setEditing(null); await reload(); } catch (requestError) { setError(requestError.message); } finally { setSaving(false); } };
  const edit = (category) => { setEditing(category._id); setForm({ name: category.name, slug: category.slug, description: category.description || "" }); setError(""); setNotice(""); };
  const remove = async (category) => { if (!window.confirm(`Deactivate category “${category.name}”?`)) return; setError(""); try { const result = await api.categories.remove(category._id); setNotice(result.message); await reload(); } catch (requestError) { setError(requestError.message); } };
  return <main className="min-h-screen bg-slate-50 px-4 py-10 sm:px-6"><div className="mx-auto max-w-7xl"><Link to="/vendor/dashboard" className="text-sm font-semibold text-orange-600">← Vendor dashboard</Link><p className="mt-5 font-semibold text-orange-600">Store workspace</p><h1 className="mt-1 text-4xl font-bold">Categories</h1><p className="mt-2 text-slate-600">Manage the categories used by your products.</p>{error && <p role="alert" className="mt-6 rounded-lg bg-red-50 p-4 text-sm text-red-700">{error}</p>}{notice && <p role="status" className="mt-6 rounded-lg bg-green-50 p-4 text-sm text-green-800">{notice}</p>}<div className="mt-8 grid gap-8 lg:grid-cols-[360px_1fr]"><form onSubmit={submit} className="h-fit space-y-4 rounded-2xl border bg-white p-5 shadow-sm"><h2 className="text-lg font-bold">{editing ? "Edit category" : "Add category"}</h2><label className="block text-sm font-medium">Name<input required value={form.name} onChange={(event) => setName(event.target.value)} className="mt-2 w-full rounded-lg border px-4 py-3" /></label><label className="block text-sm font-medium">Slug<input required value={form.slug} onChange={(event) => setForm((current) => ({ ...current, slug: event.target.value }))} className="mt-2 w-full rounded-lg border px-4 py-3" /></label><label className="block text-sm font-medium">Description<textarea rows="4" value={form.description} onChange={(event) => setForm((current) => ({ ...current, description: event.target.value }))} className="mt-2 w-full rounded-lg border px-4 py-3" /></label><div className="flex gap-3"><button disabled={saving} className="flex-1 rounded-lg bg-orange-500 px-4 py-3 font-semibold text-white disabled:opacity-60">{saving ? "Saving…" : editing ? "Save category" : "Add category"}</button>{editing && <button type="button" onClick={() => { setEditing(null); setForm(blank); }} className="rounded-lg border px-4 py-3 font-semibold">Cancel</button>}</div></form><section className="overflow-hidden rounded-2xl border bg-white shadow-sm"><div className="border-b p-5"><h2 className="font-bold">Store categories</h2></div>{loading ? <p className="p-8 text-center text-slate-500">Loading categories…</p> : <div className="divide-y">{categories.map((category) => <div key={category._id} className="flex flex-col justify-between gap-3 p-5 sm:flex-row sm:items-center"><div><h3 className="font-semibold">{category.name}</h3><p className="mt-1 text-sm text-slate-500">/{category.slug}{category.description ? ` · ${category.description}` : ""}</p></div><div className="flex gap-3"><button onClick={() => edit(category)} className="rounded-lg border px-4 py-2 text-sm font-semibold">Edit</button><button onClick={() => remove(category)} className="rounded-lg border border-red-200 px-4 py-2 text-sm font-semibold text-red-600">Deactivate</button></div></div>)}{!categories.length && <p className="p-8 text-center text-slate-500">No categories yet. Add one to start listing products.</p>}</div>}</section></div></div></main>;
}
